.bulk-dialog { padding: 16px; gap: 12px; overflow-y: auto; display: grid; }
.bulk-dialog h2 { font-size: 15px; margin: 0px; }
.bulk-bar--bottom { top: auto; bottom: 12px; margin: 8px 12px; box-shadow: var(--shadow-3); }
.detail-tab__filters { padding: 8px 16px; }
.detail-history { padding: 0px 8px 16px; }
fieldset.detail-tab__filters { border: 0px; margin: 0px; min-width: 0px; }
dialog.bulk-modal { padding: 0px; margin: 12vh auto auto; color: var(--text); }
dialog.bulk-modal::backdrop { background: var(--backdrop); backdrop-filter: blur(3px); }
.menu-button svg { color: var(--text-2); }
.menu-button svg:last-child { color: var(--text-3); margin-left: 2px; }
.button.sel__button { width: auto; justify-content: flex-start; }
.button.sel__button .sel__value { max-width: 16ch; }
.panel-header__actions .push, .bulk-bar .push { margin-left: auto; }
.sel__label { display: inline-flex; align-items: center; gap: 8px; min-width: 0px; }
.initials { width: 20px; height: 20px; border-radius: 50%; display: inline-grid; place-items: center; flex: 0 0 auto; font-size: 9.5px; font-weight: 700; background: var(--accent-soft); color: var(--accent-strong); }
.initials--none { background: var(--surface-3); color: var(--text-3); }
.menu-option { display: grid; grid-template-columns: 16px 1fr; align-items: start; justify-content: start; gap: 8px; }
.menu-option__dot { width: 8px; height: 8px; border-radius: 50%; margin: 6px 0px 0px 4px; background: var(--text-3); }
.menu-option__text { display: grid; gap: 1px; }
.menu-option__text .subtle { font-size: 12px; }
.decision { display: grid; gap: 8px; padding: 12px; border-radius: var(--r-2); background: var(--surface-2); border: 1px solid var(--line); font-size: 13px; }
.decision__foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
.detail-tab > .panel-body:first-child { padding-top: 14px; }
